/**
 * Compact per-card metadata for pool cards (generated by scripts/lib/deck-roulette-meta.mjs):
 * functional roles and the facts needed to check Extra Deck reachability.
 * Mirrors ROLE_BITS / KIND_CODES of that script.
 */

export const ROLE_BITS = {
  starter: 1,
  extender: 2,
  handtrap: 4,
  interaction: 8,
  removal: 16,
  draw: 32,
} as const;

export type CardRole = keyof typeof ROLE_BITS;
export const CARD_ROLES = Object.keys(ROLE_BITS) as CardRole[];

export const KIND = {
  other: 0,
  monster: 1,
  spell: 2,
  trap: 3,
  fusion: 4,
  synchro: 5,
  xyz: 6,
  link: 7,
} as const;

/** Finer functional flags (mirrors FLAG_BITS in scripts/lib/deck-roulette-meta.mjs). */
export const FLAG = {
  search: 1,
  ssDeck: 2,
  ssHand: 4,
  ssGy: 8,
  gyFill: 16,
  gyUse: 32,
  quick: 64,
  trigger: 128,
  continuous: 256,
  negate: 512,
  removal: 1024,
  draw: 2048,
  handtrap: 4096,
  normalSummonable: 8192,
  ritualMonster: 16384,
  ritualSpell: 32768,
} as const;

export interface CardMeta {
  roles: number;
  kind: number;
  /** Level for main monsters, Level for Synchro, Rank for Xyz, Link rating for Link. */
  level: number;
  tuner: boolean;
  /** Bit set of FLAG values; 0 when unknown. */
  flags: number;
  /** Index into the archetype list of cards.json; 0 = no archetype. */
  archetype: number;
}

/** `[roleMask, kind, level, tuner, flagMask?, archetypeIndex?]` as stored in cards.json. */
export type CardMetaTuple = readonly [number, number, number, number, number?, number?];

export function metaMapFromRecord(record: Readonly<Record<string, CardMetaTuple>>): Map<number, CardMeta> {
  const map = new Map<number, CardMeta>();
  for (const [id, [roles, kind, level, tuner, flags, archetype]] of Object.entries(record)) {
    map.set(Number(id), { roles, kind, level, tuner: tuner === 1, flags: flags ?? 0, archetype: archetype ?? 0 });
  }
  return map;
}

export function hasRole(meta: CardMeta | undefined, role: CardRole): boolean {
  return !!meta && (meta.roles & ROLE_BITS[role]) !== 0;
}

export function rolesOf(meta: CardMeta | undefined): CardRole[] {
  return meta ? CARD_ROLES.filter((role) => (meta.roles & ROLE_BITS[role]) !== 0) : [];
}

export function isExtraKind(kind: number): boolean {
  return kind === KIND.fusion || kind === KIND.synchro || kind === KIND.xyz || kind === KIND.link;
}

/** Role copies in a main deck, e.g. `{ starter: 12, handtrap: 3 }`. */
export function countRoles(
  copies: Iterable<[number, number]>,
  meta: ReadonlyMap<number, CardMeta>,
): Record<CardRole, number> {
  const counts = Object.fromEntries(CARD_ROLES.map((role) => [role, 0])) as Record<CardRole, number>;
  for (const [id, qty] of copies) {
    for (const role of rolesOf(meta.get(id))) counts[role] += qty;
  }
  return counts;
}

export function hasFlag(meta: CardMeta | undefined, flag: number): boolean {
  return !!meta && (meta.flags & flag) !== 0;
}
